// Icon shortlist data for the /icons review page.
// SVG markup itself lives in lib/icon-svgs.ts (generated by scripts/fetch-icons.mjs).

export interface IconOption {
  /** Iconify id, prefix:name — key into iconSvgs. "css-live-dot" is a special local render. */
  id: string;
  /** Additional ids rendered next to the primary one (e.g. a pair). */
  extraIds?: string[];
  set: string;
  style: "outline" | "solid" | "filled";
  why: string;
  recommended?: boolean;
}

export interface IconConcept {
  name: string;
  currentEmoji: string | null;
  usage: string;
  options: IconOption[];
}

export const strategyPoints: string[] = [
  "Standardise on Lucide (the site already ships lucide-react 0.446 for UI icons) + Lucide Lab for sports — same 24px grid and 2px stroke, so they read as one visually identical family. MDI is the single sanctioned fallback set for the gaps (AFL, handball, boxing, MMA, snooker, checkered flag).",
  "Tabler options are near-identical geometry to Lucide and are listed as alternates throughout.",
  "Rugby codes currently share 🏉 — proposal: union = outline ball (lucide-lab), league = solid ball (mdi), AFL = pointed oval (mdi:football-australian). Three-way distinction.",
  "Handball has NO ball-only icon in any major set — all options are player-action glyphs.",
  "Snooker/pool has no clean outline 8-ball — mdi:eight-ball (solid) is recommended; a solid circle survives next to outlines.",
  "No good checkered flag in the Lucide family — mdi:flag-checkered is the forced exception.",
  "game-icons has a literal F1 car, but it's CC BY 3.0 (attribution required) and a heavier filled 512-grid style.",
  "Licenses: Lucide/Lucide Lab ISC, Tabler MIT, MDI Apache-2.0, Iconoir MIT, Phosphor MIT, game-icons CC BY 3.0.",
];

